const urls=new Map();
function open(){return new Promise((resolve,reject)=>{const req=indexedDB.open('pocket-trial-assets-v3',1);req.onupgradeneeded=()=>req.result.createObjectStore('assets',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('本机素材存储不可用'));});}
async function store(mode,action){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('assets',mode),request=action(tx.objectStore('assets'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(Error('本机素材写入失败'));};});}
export async function trialAssets(){const list=await store('readonly',s=>s.getAll());for(const a of list)if(!urls.has(a.id))urls.set(a.id,URL.createObjectURL(a.blob));return list.filter(a=>!a.hidden).map(({blob,...a})=>({...a,url:'/local-assets/'+a.id}));}
export async function putTrialAsset(file,originalSize,name){const id=crypto.randomUUID(),asset={id,name,mime:file.type,size:file.size,original_size:originalSize,blob:file,hidden:false};await store('readwrite',s=>s.put(asset));urls.set(id,URL.createObjectURL(file));return {id,url:'/local-assets/'+id};}
export async function hideTrialAsset(id){const a=await store('readonly',s=>s.get(id));if(a){a.hidden=true;await store('readwrite',s=>s.put(a));}}
export function resolveMedia(src){if(typeof src==='string'&&src.startsWith('/local-assets/'))return urls.get(src.slice(14))||'';return src;}
export async function promoteTrialDocument(doc,api){const out=structuredClone(doc),refs=[...new Set([...JSON.stringify(out).matchAll(/\/local-assets\/([\w-]+)/g)].map(x=>x[1]))],replacements=new Map();for(const id of refs){const asset=await store('readonly',s=>s.get(id));if(!asset)throw Error('本机试用素材缺失，转入已停止');const uploaded=await api('assets',{method:'POST',body:asset.blob,headers:{'Content-Type':asset.mime,'X-File-Name':encodeURIComponent(asset.name),'X-Original-Size':String(asset.original_size)}});replacements.set('/local-assets/'+id,uploaded.url);}const visit=x=>{if(Array.isArray(x))return x.map(visit);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,visit(v)]));return replacements.get(x)||x;};return visit(out);}
